private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (Convert.ToDouble(GetCurrentColumnValue("DETYRIMIMeparshem")) > 0)
            {
                debi = Convert.ToDouble(GetCurrentColumnValue("DETYRIMIMeparshem"));
                xrTableCell14.Text = String.Format("{0:#,#.00}", (debi));
                xrTableCell15.Text = " ";
                totGrupiDebi += debi;
                ShTotGrupiDebi += debi;

            }
            else
            {
                kredi = (-1) * Convert.ToDouble(GetCurrentColumnValue("DETYRIMIMeparshem"));
                xrTableCell15.Text = String.Format("{0:#,#.00}", (kredi));
                xrTableCell14.Text = " ";
                totGrupKredi += kredi;
                ShTotGrupiKredi += kredi;
            }


           if (GetCurrentColumnValue("KODKLIENTFURNITOR") != null)
            {
                cnt++;
                xrTableCell10.Text = cnt.ToString();
            }

}

